,p_display_name=>'APEX Dynamic Controller'
,p_category=>'NAVIGATION'
,p_javascript_file_urls=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#PLUGIN_FILES#adc/js/utils.js',
